#include <bits/stdc++.h>
using namespace std;

int main() {
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    int N=3*n;
	    vector<long long>a(N);
	    for(auto &x:a){
	        cin>>x;
	        
	    }
	    sort(a.begin(),a.end(),greater<long long>());
	    vector<long long>pref(N+1,0);
	    for(int i=0;i<N;i++){
	        pref[i+1]=pref[i]+a[i];
	    }
	    long long ans=0;
	    for(int A=0;A<=n;++A){
	        int low=0;
	        int high=n-A;
	        while(low<high){
	            int B=(low+high)/2;
	            int i=A+2*B;
	            int j=N-2*A-B-1;
	            long long diff=a[i]+a[i+1]-3LL*a[j];
	            if(diff>=0){
	                low=B+1;
	            }
	            else{
	                high=B;
	            }
	        }
	            for(int B:{low-1,low}){
	                if(B<0 || B>(n-A)){
	                    continue;
	                }
	                int p1=A;
	                int p2=A+2*B;
	                int p3=N-2*A-B;
	                long long cur=2LL*pref[p1]+pref[p2]+3LL*pref[p3];
	                ans=max(ans,cur);
	            }
	        }
	        
	    
	    cout<<ans<<endl;
	}

}
